
import pingouin as pg; import pandas as pd; import numpy as np; np.random.seed(7); n_subjects = 5; subjects =                           np.tile(np.arange(n_subjects), 4); factor1 = np.repeat(['low', 'high'], n_subjects * 2); factor2 = np.tile(np.repeat(['pre', 'post'],               n_subjects), 2); scores = np.concatenate([np.random.normal(loc=10, scale=2, size=n_subjects), np.random.normal(loc=12, scale=2, size=n_subjects),np.random.normal(loc=16, scale=2, size=n_subjects), np.random.normal(loc=18, scale=2, size=n_subjects)]); data = pd.DataFrame({'subject':subjects, 'dose': factor1, 'time': factor2, 'score': scores}); result = pg.rm_anova(data=data, dv='score', within=['dose', 'time'],subject='subject', detailed=True); print('Column names in pingouin rm_anova result:'); print(result.columns.tolist()); print('\nDataFrame:'); print(result)